//! Reference parity tests.
//!
//! Expected values were generated by driving the original PrayTimes.js v2.3
//! source (PrayTimes.org) with the same parameters, locations and dates as
//! used here, in `Float` time format. See `tests/fixtures/praytimes/` for
//! the harness and the raw `reference.json` it produced.
//!
//! The Rust port runs 2 solver iterations vs PrayTimes' 1, so outputs can
//! differ by a fraction of a minute; bore tolerances account for that plus
//! the float rounding of the expected values.
//!
//! Known, intentionally tested deviations from the upstream JS behavior are
//! documented on the individual assertions.

mod common;

use common::{assert_minutes_close, request, request_full, request_with_settings};
use prayer_times_calculator::{
    calculator::PrayerCalculator,
    methods,
    models::{
        AngleOrMinutes, AsrJuristic, HighLatMethod, MidnightMode, Params, Settings, TimeOffsets,
    },
};

const TOL: f64 = 2.0; // parity tolerance in minutes for ordinary cases
const TOL_EDGE: f64 = 3.0; // looser tolerance for extreme-latitude edge cases

// ---------------------------------------------------------------
// Parity with the original PrayTimes.js v2.3
// ---------------------------------------------------------------

#[test]
fn mecca_makkah_mid_june_matches_praytimes() {
    // Umm al-Qura: fajr 18.5°, isha = maghrib + 90 min
    let t = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        21.4225,
        39.8262,
        0.0,
        3.0,
        methods::makkah(),
    ))
    .unwrap();

    assert_minutes_close(t.fajr, 4.167, TOL); // 04:10
    assert_minutes_close(t.sunrise, 5.633, TOL); // 05:38
    assert_minutes_close(t.dhuhr, 12.350, TOL); // 12:21
    assert_minutes_close(t.asr, 15.667, TOL); // 15:40
    assert_minutes_close(t.sunset, 19.067, TOL); // 19:04
    assert_minutes_close(t.maghrib, 19.067, TOL);
    assert_minutes_close(t.isha, 20.567, TOL); // 20:34
    assert_minutes_close(t.midnight, 24.350, TOL); // 00:21 next day
}

