/// The port derives imsak from `params.fajr`; every preset uses an angle for
/// fajr, so imsak ends up identical to fajr here. This deviates from upstream
/// PrayTimes (default imsak setting is '10 min', i.e. fajr-10) — it is the
/// pinned behavior of this implementation.
#[test]
fn imsak_equals_fajr_for_angle_fajr_methods() {
    let t = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        21.4225,
        39.8262,
        0.0,
        3.0,
        methods::makkah(),
    ))
    .unwrap();
    assert!((t.imsak - t.fajr).abs() < 1e-9);
}

