// ---------------------------------------------------------------
// Structural behavior: offsets, high-lat formulas, midnight modes.
// ---------------------------------------------------------------

#[test]
fn minute_offsets_shift_fields_by_offset_over_sixty() {
    let base = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        21.4225,
        39.8262,
        0.0,
        3.0,
        methods::makkah(),
    ))
    .unwrap();
    let shifted = PrayerCalculator::calculate(&request_full(
        2026,
        6,
        14,
        21.4225,
        39.8262,
        0.0,
        3.0,
        methods::makkah(),
        Settings::default(),
        TimeOffsets {
            imsak: -10.0,
            fajr: 10.0,
            sunrise: -2.0,
            dhuhr: 3.0,
            asr: -7.0,
            sunset: 5.0,
            maghrib: 5.0,
            isha: -5.0,
            midnight: 2.0,
        },
    ))
    .unwrap();

    assert_minutes_close(shifted.imsak - base.imsak, -10.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.fajr - base.fajr, 10.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.sunrise - base.sunrise, -2.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.dhuhr - base.dhuhr, 3.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.asr - base.asr, -7.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.sunset - base.sunset, 5.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.maghrib - base.maghrib, 5.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.isha - base.isha, -5.0 / 60.0, 1e-6);
    assert_minutes_close(shifted.midnight - base.midnight, 2.0 / 60.0, 1e-6);
}

#[test]
fn longitude_drifts_dhuhr_by_four_minutes_per_degree() {
    // Holding timezone fixed, solar noon shifts ~4 min per degree of longitude.
    let west = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        21.4225,
        30.0,
        0.0,
        0.0,
        methods::makkah(),
    ))
    .unwrap();
    let east = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        21.4225,
        45.0,
        0.0,
        0.0,
        methods::makkah(),
    ))
    .unwrap();
    // 15° * 4 min/° — east should noon earlier
    let delta = (east.dhuhr - west.dhuhr) * 60.0;
    assert!(
        (delta + 60.0).abs() < 2.0,
        "dhuhr shifted by {delta} min for 15° eastward drift (expected ~-60)"
    );
}

#[test]
fn anglebased_portion_matches_angle_over_sixty_of_night() {
    // Reykjavík in June: both the 18° fajr and 17° isha angles are unsolvable,
    // so the adjustment triggers. Night length = 24h - day length.
    let t = PrayerCalculator::calculate(&request_with_settings(
        2026,
        6,
        14,
        64.1466,
        -21.9426,
        0.0,
        0.0,
        methods::mwl(),
        Settings {
            high_lats: HighLatMethod::AngleBased,
            ..Settings::default()
        },
    ))
    .unwrap();
    let night = 24.0 - (t.sunset - t.sunrise);
    let fajr_portion = 18.0 / 60.0 * night;
    let isha_portion = 17.0 / 60.0 * night;
    assert!((t.fajr - (t.sunrise - fajr_portion)).abs() < 1e-3);
    assert!((t.isha - (t.sunset + isha_portion)).abs() < 1e-3);
}

#[test]
fn oneseventh_portion_is_one_seventh_of_night() {
    let t = PrayerCalculator::calculate(&request_with_settings(
        2026,
        6,
        1,
        52.5200,
        13.4050,
        0.0,
        2.0,
        methods::mwl(),
        Settings {
            high_lats: HighLatMethod::OneSeventh,
            ..Settings::default()
        },
    ))
    .unwrap();
    let night = 24.0 - (t.sunset - t.sunrise);
    assert!((t.fajr - (t.sunrise - night / 7.0)).abs() < 1e-3);
    assert!((t.isha - (t.sunset + night / 7.0)).abs() < 1e-3);
}

#[test]
fn nightmiddle_portion_is_half_the_night() {
    // Reykjavík is far enough north that NightMiddle triggers for fajr.
    // The clamped isha happens to fall within the half-night portion (1.49 h),
    // so only fajr is formula-adjusted; isha must still end up no further
    // than half a night past sunset.
    let t = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        64.1466,
        -21.9426,
        0.0,
        0.0,
        methods::mwl(),
    ))
    .unwrap();
    let night = 24.0 - (t.sunset - t.sunrise);
    let portion = night / 2.0;
    assert!((t.fajr - (t.sunrise - portion)).abs() < 1e-3);
    let isha_late = t.isha - t.sunset;
    assert!(
        (0.0..=portion + 1e-3).contains(&isha_late),
        "isha sits {isha_late} h after sunset, beyond the half-night portion {portion} h"
    );
}

#[test]
fn no_adjustment_for_none_high_lats() {
    // Murmansk at the equinox: solutions exist, no adjustment should fire,
    // nor should the None method clamp anything.
    let none = PrayerCalculator::calculate(&request_with_settings(
        2026,
        3,
        20,
        68.9585,
        33.0827,
        0.0,
        3.0,
        methods::mwl(),
        Settings {
            high_lats: HighLatMethod::None,
            ..Settings::default()
        },
    ))
    .unwrap();
    let middle = PrayerCalculator::calculate(&request(
        2026,
        3,
        20,
        68.9585,
        33.0827,
        0.0,
        3.0,
        methods::mwl(),
    ))
    .unwrap();

    assert_minutes_close(none.fajr, middle.fajr, 1e-6);
    assert_minutes_close(none.isha, middle.isha, 1e-6);
    assert!(none.fajr < none.sunrise);
}

