#[test]
fn timezones_move_all_times_by_one_hour_per_hour() {
    let a = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        21.4225,
        39.8262,
        0.0,
        3.0,
        methods::makkah(),
    ))
    .unwrap();
    let b = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        21.4225,
        39.8262,
        0.0,
        4.0,
        methods::makkah(),
    ))
    .unwrap();

    for (x, y) in [
        (a.imsak, b.imsak),
        (a.fajr, b.fajr),
        (a.sunrise, b.sunrise),
        (a.dhuhr, b.dhuhr),
        (a.asr, b.asr),
        (a.sunset, b.sunset),
        (a.maghrib, b.maghrib),
        (a.isha, b.isha),
        (a.midnight, b.midnight),
    ] {
        let delta = (y - x) * 60.0;
        assert!(
            (delta - 60.0).abs() < 2.0,
            "one hour of timezone should move times by ~60 min, got {delta}"
        );
    }
}

#[test]
fn hanafi_asr_is_later_than_standard() {
    let standard = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        40.7128,
        -74.0060,
        0.0,
        -4.0,
        methods::isna(),
    ))
    .unwrap();
    let hanafi = PrayerCalculator::calculate(&request_with_settings(
        2026,
        6,
        14,
        40.7128,
        -74.0060,
        0.0,
        -4.0,
        methods::isna(),
        Settings {
            asr: AsrJuristic::Hanafi,
            ..Settings::default()
        },
    ))
    .unwrap();

    assert!(
        hanafi.asr > standard.asr,
        "Hanafi asr ({}) should come after the Shafi'i one ({})",
        hanafi.asr,
        standard.asr
    );
    // At 40°N in June the gap is typically 45-75 minutes
    let gap = (hanafi.asr - standard.asr) * 60.0;
    assert!(
        (30.0..120.0).contains(&gap),
        "asr gap of {gap} min is outside the plausible range (30..120)"
    );
}

#[test]
fn custom_asr_factor_interpolates_between_standard_and_hanafi() {
    let standard = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        1.3521,
        103.8198,
        0.0,
        8.0,
        methods::singapore(),
    ))
    .unwrap();
    let custom = PrayerCalculator::calculate(&request_with_settings(
        2026,
        6,
        14,
        1.3521,
        103.8198,
        0.0,
        8.0,
        methods::singapore(),
        Settings {
            asr: AsrJuristic::Custom(1.5),
            ..Settings::default()
        },
    ))
    .unwrap();
    let hanafi = PrayerCalculator::calculate(&request_with_settings(
        2026,
        6,
        14,
        1.3521,
        103.8198,
        0.0,
        8.0,
        methods::singapore(),
        Settings {
            asr: AsrJuristic::Hanafi,
            ..Settings::default()
        },
    ))
    .unwrap();

    assert!(
        custom.asr > standard.asr,
        "factor 1.5 should be later than standard (factor 1)"
    );
    assert!(
        custom.asr < hanafi.asr,
        "factor 1.5 should be earlier than hanafi (factor 2)"
    );
}

#[test]
fn elevation_pulls_sunrise_earlier_and_sunset_later() {
    let flat = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        25.2048,
        55.2708,
        0.0,
        4.0,
        methods::dubai(),
    ))
    .unwrap();
    let high = PrayerCalculator::calculate(&request(
        2026,
        6,
        14,
        25.2048,
        55.2708,
        200.0,
        4.0,
        methods::dubai(),
    ))
    .unwrap();

    assert!(
        high.sunrise < flat.sunrise,
        "200 m elevation should make sunrise earlier"
    );
    assert!(
        high.sunset > flat.sunset,
        "200 m elevation should make sunset later"
    );

    // rise_set_angle delta is 0.0347 * sqrt(200) ≈ 0.49° — a few minutes
    let sr_gap = (flat.sunrise - high.sunrise) * 60.0;
    let ss_gap = (high.sunset - flat.sunset) * 60.0;
    assert!(
        (1.0..8.0).contains(&sr_gap),
        "sunrise gap of {sr_gap} min unexpected"
    );
    assert!(
        (1.0..8.0).contains(&ss_gap),
        "sunset gap of {ss_gap} min unexpected"
    );
}

#[test]
fn calculation_is_deterministic() {
    let req = request(2026, 6, 14, 51.5074, -0.1278, 0.0, 1.0, methods::mwl());
    let a = PrayerCalculator::calculate(&req).unwrap();
    let b = PrayerCalculator::calculate(&req).unwrap();
    assert_eq!(a, b);
}
